'use strict';
const transitionSurfaces=new Map();
function sceneSurface(name){let canvas=transitionSurfaces.get(name);if(!canvas){canvas=document.createElement('canvas');transitionSurfaces.set(name,canvas)}if(canvas.width!==$('stage').width||canvas.height!==$('stage').height){canvas.width=$('stage').width;canvas.height=$('stage').height}return canvas}
function withSceneTime(s,t,fn){const original={sceneIndex,time};try{sceneIndex=project.scenes.indexOf(s);time=t;return fn()}finally{sceneIndex=original.sceneIndex;time=original.time}}
function renderSceneFrame(c,s,t,{skip=new Set(),texture=true}={}){return withSceneTime(s,t,()=>{const w=c.canvas.width,h=c.canvas.height;c.save();c.setTransform(w/960,0,0,h/540,0,0);c.clearRect(0,0,960,540);rect(c,0,0,960,540,s.bg);if(s.template==='studio'){circle(c,935,10,160,'#dce4ce');rect(c,0,448,960,92,'#eadcc0');line(c,0,448,960,448,'#d8c6a4',2)}if(s.template==='board'){rect(c,48,44,864,406,'#31574e',12);rect(c,40,441,880,12,'#b98758',4)}c.save();applyCamera(c,s,t);drawBackground(c,s);for(const o of s.objects){if(skip.has(o.id)||!visibleAt(o,t,s))continue;const v=stateAt(o,t);c.save();applyVisualEffects(c,o,v,t);if(o.type==='character')character(c,o.character,v,lipExpression(o,t));else if(o.type==='video')drawVideoObject(c,o,v);else prop(c,o,v);c.restore()}c.restore();drawCaptions(c,s,t);if(texture){c.save();c.globalAlpha=.65;c.fillStyle=c.createPattern(grain,'repeat');c.fillRect(0,0,960,540);c.restore()}c.restore()})}
function openingVideoFrames(s){for(const o of s.objects.filter(o=>o.type==='video'&&visibleAt(o,0,s))){const video=videoFor(o);video.pause();if(video.readyState>=2&&!video.seeking&&Math.abs(video.currentTime-o.sourceOffset)>.03)video.currentTime=o.sourceOffset}}
function transitionMatches(a,b,t){const used=new Set(),pairs=[];for(const from of a.objects.filter(o=>visibleAt(o,t,a))){const name=from.transitionTag||from.name;if(!name)continue;const to=b.objects.find(o=>!used.has(o.id)&&o.type===from.type&&(o.transitionTag||o.name)===name&&visibleAt(o,0,b));if(to){used.add(to.id);pairs.push({from,to})}}return pairs}
function screenPose(s,o,t){const v=stateAt(o,t),cam=cameraAt(s,t);return{...v,x:480+(v.x-cam.x)*cam.zoom,y:270+(v.y-cam.y)*cam.zoom,scale:v.scale*cam.zoom}}
for(const [value,label]of[['crossfade','Crossfade to next scene'],['slide-left','Slide left'],['slide-right','Slide right'],['zoom','Zoom to next scene'],['match','Match objects by name / tag']]){const option=document.createElement('option');option.value=value;option.textContent=label;$('transition').append(option)}
$('transitionLength').parentElement.insertAdjacentHTML('afterend','<p class="note transition-note">Scene transitions reveal the next scene’s opening frame. Scene timing stays unchanged. Match transitions pair layers with the same name or match tag.</p>');
const simpleSceneTransition=drawSceneTransition;
drawSceneTransition=function(c,s,t){if(!['crossfade','slide-left','slide-right','zoom','match'].includes(s.transition))return simpleSceneTransition(c,s,t);const next=project.scenes[project.scenes.indexOf(s)+1];if(!next)return;const duration=Math.min(s.transitionDuration??.5,s.duration),raw=clamp((t-s.duration+duration)/duration,0,1);if(raw<=0)return;const f=raw*raw*(3-2*raw),out=sceneSurface('out'),incoming=sceneSurface('in');openingVideoFrames(next);const pairs=s.transition==='match'?transitionMatches(s,next,t):[],skipOut=new Set(pairs.map(p=>p.from.id)),skipIn=new Set(pairs.map(p=>p.to.id));renderSceneFrame(out.getContext('2d'),s,t,{skip:skipOut});renderSceneFrame(incoming.getContext('2d'),next,0,{skip:skipIn});c.save();c.setTransform(c.canvas.width/960,0,0,c.canvas.height/540,0,0);rect(c,0,0,960,540,s.bg);if(s.transition==='slide-left'||s.transition==='slide-right'){const direction=s.transition==='slide-left'?-1:1;c.drawImage(out,960*direction*f,0,960,540);c.drawImage(incoming,-960*direction*(1-f),0,960,540)}else if(s.transition==='zoom'){c.save();c.translate(480,270);c.scale(1-f*.12,1-f*.12);c.globalAlpha=1-f;c.drawImage(out,-480,-270,960,540);c.restore();c.save();c.translate(480,270);const zoom=1.18-.18*f;c.scale(zoom,zoom);c.globalAlpha=f;c.drawImage(incoming,-480,-270,960,540);c.restore()}else{c.drawImage(out,0,0,960,540);c.globalAlpha=f;c.drawImage(incoming,0,0,960,540);c.globalAlpha=1}for(const {from,to}of pairs){const a=screenPose(s,from,t),b=screenPose(next,to,0),v={};for(const key of new Set([...Object.keys(a),...Object.keys(b)])){v[key]=Number.isFinite(a[key])&&Number.isFinite(b[key])?a[key]+(b[key]-a[key])*f:(f<.5?a[key]:b[key])}const chosen=f<.5?from:to;withSceneTime(f<.5?s:next,f<.5?t:0,()=>{c.save();if(chosen.type==='character')character(c,chosen.character,v,lipExpression(chosen,time));else if(chosen.type==='video')drawVideoObject(c,chosen,v);else prop(c,chosen,v);c.restore()})}c.restore()};
const controlsBeforeMatching=renderControls;renderControls=function(){controlsBeforeMatching();const o=object();if(!o)return;const label=document.createElement('label');label.textContent='Match tag';const input=document.createElement('input');input.id='transitionMatchTag';input.maxLength=60;input.placeholder='e.g. presenter';input.value=o.transitionTag||'';input.disabled=!!o.locked;input.onchange=()=>{if(o.locked)return;o.transitionTag=input.value.trim();save()};label.append(input);$('controls').append(label)};
render();
